// Single-file copy of supabase/functions/partner-monthly-report/index.ts for deploying from the
// Supabase dashboard. Generated by supabase/build-dashboard-functions.mjs — do not edit.

import "jsr:@supabase/functions-js/edge-runtime.d.ts";

/**
 * Monthly partner report (promised on firdam.com/partners: "Every month we
 * send you how many families tapped through to your shop").
 *
 * Runs on the 1st of each month from the database scheduler (pg_cron job
 * "partner-monthly-report", see migration 20261107100000) and emails every active partner how many times families tapped through to them
 * last month and since they joined. Numbers only: never who the families are.
 *
 * POST, header x-report-token: the Vault secret "partner_report_token"
 * body { month?: "2026-10", dryRun?: true }
 * Each partner gets one email per month (checked against email_log), so a re-run is safe.
 *
 * Secrets: RESEND_API_KEY (+ EMAIL_FROM, EMAIL_REPLY_TO, optional). The token lives
 * only in Supabase Vault and is checked by public.check_partner_report_token().
 */

function env(name: string): string | undefined {
  const v = Deno.env.get(name);
  return v && v.trim() ? v.trim() : undefined;
}

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body, null, 1), { status, headers: { "Content-Type": "application/json" } });
}

function escapeHtml(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function toHtml(text: string): string {
  const body = escapeHtml(text)
    .split(/\n{2,}/)
    .map((p) => `<p style="margin:0 0 14px">${p.replace(/\n/g, "<br>")}</p>`)
    .join("")
    .replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" style="color:#8a5a3b">$1</a>');
  return `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#2b211b;max-width:600px">${body}</div>`;
}

interface Shop {
  id: string;
  name: string;
  discount_code: string | null;
  discount_text: string | null;
  free_until: string | null;
  created_at: string;
  application_id: string | null;
}

Deno.serve(async (req) => {
  if (req.method !== "POST") return json({ error: "Use POST." }, 405);
  const url = env("SUPABASE_URL")!;
  const service = env("SUPABASE_SERVICE_ROLE_KEY")!;
  const headers = { apikey: service, Authorization: `Bearer ${service}`, "Content-Type": "application/json" };
  const check = await fetch(`${url}/rest/v1/rpc/check_partner_report_token`, {
    method: "POST",
    headers,
    body: JSON.stringify({ p_token: req.headers.get("x-report-token") ?? "" }),
  });
  if (!check.ok || (await check.json()) !== true) return json({ error: "Not allowed." }, 403);
  const rest = async <T>(path: string): Promise<T> => {
    const res = await fetch(`${url}/rest/v1/${path}`, { headers });
    if (!res.ok) throw new Error(`${path}: ${res.status} ${await res.text()}`);
    return (await res.json()) as T;
  };

  const body = (await req.json().catch(() => ({}))) as { month?: string; dryRun?: boolean };
  // Default: the month that just ended (UTC).
  const now = new Date();
  const [y, m] = body.month && /^\d{4}-\d{2}$/.test(body.month)
    ? body.month.split("-").map(Number)
    : [now.getUTCMonth() === 0 ? now.getUTCFullYear() - 1 : now.getUTCFullYear(), now.getUTCMonth() === 0 ? 12 : now.getUTCMonth()];
  const from = new Date(Date.UTC(y, m - 1, 1)).toISOString();
  const to = new Date(Date.UTC(y, m, 1)).toISOString();
  const monthName = new Date(Date.UTC(y, m - 1, 15)).toLocaleDateString("en-CA", { month: "long", year: "numeric", timeZone: "UTC" });

  const shops = await rest<Shop[]>("partner_shops?select=id,name,discount_code,discount_text,free_until,created_at,application_id&active=eq.true");
  const contacts = await rest<{ partner_id: string; owner_name: string | null; email: string | null }[]>("partner_contacts?select=partner_id,owner_name,email");
  const appIds = shops.map((s) => s.application_id).filter(Boolean);
  const apps = appIds.length
    ? await rest<{ id: string; owner_name: string | null; email: string | null }[]>(`partner_applications?select=id,owner_name,email&id=in.(${appIds.join(",")})`)
    : [];
  const clicks = await rest<{ partner_id: string; created_at: string }[]>(`partner_clicks?select=partner_id,created_at&created_at=lt.${encodeURIComponent(to)}`);
  const sent = await rest<{ to_email: string; subject: string }[]>(`email_log?select=to_email,subject&created_at=gte.${encodeURIComponent(to)}`);

  const from_ = env("EMAIL_FROM") ?? "Firdam <partners@firdam.com>";
  const replyTo = env("EMAIL_REPLY_TO") ?? "support@firdam.com";
  const key = env("RESEND_API_KEY");
  const results: unknown[] = [];

  for (const shop of shops) {
    const contact = contacts.find((c) => c.partner_id === shop.id);
    const app = apps.find((a) => a.id === shop.application_id);
    const email = (contact?.email || app?.email || "").trim();
    const owner = ((contact?.owner_name || app?.owner_name || "").trim().split(/\s+/)[0]) || "";
    const mine = clicks.filter((c) => c.partner_id === shop.id);
    const month = mine.filter((c) => c.created_at >= from).length;
    const total = mine.length;
    // Partners who joined after the month ended get their first report next month.
    if (shop.created_at >= to) {
      results.push({ shop: shop.name, skipped: "joined after this month" });
      continue;
    }
    if (!email) {
      results.push({ shop: shop.name, month, total, skipped: "no email on file" });
      continue;
    }
    const subject = `Your Firdam report for ${monthName}: ${shop.name}`;
    if (sent.some((s) => s.to_email === email && s.subject === subject)) {
      results.push({ shop: shop.name, email, month, total, skipped: "already sent" });
      continue;
    }

    const offer = [shop.discount_text, shop.discount_code ? `code ${shop.discount_code}` : ""].filter(Boolean).join(", ");
    const free = shop.free_until
      ? `As a founding partner, your listing stays free until ${new Date(shop.free_until + "T12:00:00Z").toLocaleDateString("en-CA", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" })}, and we never charge anything unless you agree in writing first.`
      : "";
    const text =
      `Assalamu alaykum${owner ? ` ${owner}` : ""},\n\n` +
      `Here is your Firdam report for ${monthName}.\n\n` +
      `Taps through to ${shop.name}: ${month} in ${monthName}, ${total} since you joined Firdam.\n\n` +
      `A tap is a family opening your shop from your Firdam listing. We only count taps; we never share who the families are.\n\n` +
      (offer ? `Your offer for Firdam families: ${offer}.\n\n` : "") +
      `If anything has changed (your offer, prices, link or photos), just reply to this email and we'll update your listing.\n\n` +
      (free ? `${free}\n\n` : "") +
      `JazakAllahu khayran for serving Firdam families.\n\nThe Firdam team\nhttps://firdam.com`;

    if (body.dryRun || !key) {
      results.push({ shop: shop.name, email, month, total, preview: !key ? "RESEND_API_KEY missing" : "dry run", subject, text });
      continue;
    }
    const res = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({ from: from_, to: [email], reply_to: replyTo, subject, text, html: toHtml(text) }),
    });
    const out = (await res.json().catch(() => ({}))) as { id?: string; message?: string };
    if (!res.ok) {
      results.push({ shop: shop.name, email, month, total, error: out.message ?? res.status });
      continue;
    }
    await fetch(`${url}/rest/v1/email_log`, {
      method: "POST",
      headers,
      body: JSON.stringify({ to_email: email, from_email: from_, subject, body: text, application_id: shop.application_id, provider_id: out.id ?? null }),
    }).catch(() => undefined);
    results.push({ shop: shop.name, email, month, total, sent: true });
  }

  return json({ month: monthName, results });
});
